function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  "use strict";
  var OPT = (typeof rec === "object" && rec && rec.__opt) ? rec.__opt : {};
  var TTYPES = ["bolt", "cannon", "frost", "lance", "flak"];
  var TDEF = {
    bolt:   { cost: 50,  dmg: 26,  period: 8,  range: 300, splash: 0,  slow: 0,  pierce: false, ground: true,  air: true },
    cannon: { cost: 90,  dmg: 60,  period: 24, range: 260, splash: 90, slow: 0,  pierce: false, ground: true,  air: false },
    frost:  { cost: 70,  dmg: 10,  period: 12, range: 240, splash: 0,  slow: 30, pierce: false, ground: true,  air: true },
    lance:  { cost: 120, dmg: 180, period: 36, range: 360, splash: 0,  slow: 0,  pierce: true,  ground: true,  air: false },
    flak:   { cost: 80,  dmg: 40,  period: 10, range: 320, splash: 70, slow: 0,  pierce: false, ground: false, air: true }
  };
  var EDEF = {
    grunt:     { hp: 60,  speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner:    { hp: 40,  speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp:      { hp: 50,  speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute:     { hp: 150, speed: 6,  bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter:  { hp: 90,  speed: 8,  bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender:    { hp: 70,  speed: 8,  bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling: { hp: 0,   speed: 12, bounty: 1, leak: 1, air: 0, first: 0, weight: 0 }
  };
  var ROLL = ["grunt", "runner", "wisp", "brute", "splitter", "mender"];
  var SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function mkRoute(pts) {
    var p = [], cum = [0], i;
    for (i = 0; i < pts.length; i++) p.push([pts[i][0] * 100 + 50, pts[i][1] * 100 + 50]);
    for (i = 1; i < p.length; i++) cum.push(cum[i - 1] + Math.abs(p[i][0] - p[i - 1][0]) + Math.abs(p[i][1] - p[i - 1][1]));
    return { p: p, cum: cum, len: cum[cum.length - 1] };
  }
  var GROUND = mkRoute([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  var AIR = mkRoute([[0,6],[21,6],[21,11],[23,11]]);
  if (OPT.airLen) AIR.len = OPT.airLen;
  function posAt(rt, d, out) {
    var p = rt.p, cum = rt.cum, n = p.length, i = 1;
    if (d <= 0) { out[0] = p[0][0]; out[1] = p[0][1]; return; }
    while (i < n - 1 && cum[i] < d) i++;
    var a = p[i - 1], b = p[i], t = d - cum[i - 1];
    var dx = b[0] > a[0] ? 1 : (b[0] < a[0] ? -1 : 0), dy = b[1] > a[1] ? 1 : (b[1] < a[1] ? -1 : 0);
    if (t > cum[i] - cum[i - 1]) t = cum[i] - cum[i - 1] + (d - cum[i]);
    out[0] = a[0] + dx * t; out[1] = a[1] + dy * t;
  }
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed | 0);
  var mulCache = [0, 1000];
  function mult(w) { while (mulCache.length <= w) mulCache.push(Math.floor(mulCache[mulCache.length - 1] * 108 / 100)); return mulCache[w]; }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], pool = [], tot = 0, i, j;
    for (i = 0; i < ROLL.length; i++) if (EDEF[ROLL[i]].first <= w) { pool.push(ROLL[i]); tot += EDEF[ROLL[i]].weight; }
    for (i = 0; i < n; i++) {
      var r = rng() % tot;
      for (j = 0; j < pool.length; j++) { var wt = EDEF[pool[j]].weight; if (r < wt) break; r -= wt; }
      out.push(pool[j]);
    }
    return out;
  }
  function tierDmg(type, tier) { var d = TDEF[type].dmg; for (var k = 1; k < tier; k++) d = Math.floor(d * 16 / 10); return d; }
  function tierRange(type, tier) { return TDEF[type].range + 30 * (tier - 1); }

  var strat = createStrategy();
  var hasTarget = strat && typeof strat.target === "function";
  var log = [];
  var gold = 250, baseHp = 10, nextId = 1, fell = false, fallTick = -1, curWave = 0;
  var turrets = new Array(16);
  for (var s0 = 0; s0 < 16; s0++) turrets[s0] = null;
  var enemies = [];          // alive, ascending id
  var queue = [];            // pending spawns
  var waves = [null];        // compositions
  waves.push(genWave(1));
  var tmp = [0, 0];

  function makeEnemy(type, wave, maxHp, progress) {
    var d = EDEF[type];
    var armor = type === "grunt" ? Math.floor(wave / 4) : (type === "brute" ? 6 + wave : 0);
    var e = { id: nextId++, type: type, wave: wave, hp: maxHp, maxHp: maxHp, armor: armor, speed: d.speed,
      air: d.air, route: d.air ? AIR : GROUND, progress: progress, slow: 0, age: 0, x: 0, y: 0, alive: true };
    posAt(e.route, e.progress, tmp); e.x = tmp[0]; e.y = tmp[1];
    return e;
  }
  function view(e) {
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: e.speed, slowed: e.slow > 0, remaining: e.route.len - e.progress };
  }
  function buildState(tick) {
    var sl = [], i;
    for (i = 0; i < 16; i++) {
      var t = turrets[i];
      sl.push({ slot: i, x: SLOTS[i][0] * 100 + 50, y: SLOTS[i][1] * 100 + 50,
        turret: t ? { type: t.type, tier: t.tier, spent: t.spent } : null });
    }
    var ev = [];
    for (i = 0; i < enemies.length; i++) ev.push(view(enemies[i]));
    return { tick: tick, wave: curWave, gold: gold, baseHp: baseHp, slots: sl, enemies: ev,
      nextWave: waves[curWave + 1].slice() };
  }
  function applyActions(acts, tick) {
    if (!acts || typeof acts.length !== "number") return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== "object") continue;
      var slot = a.slot;
      if (typeof slot !== "number" || slot !== Math.floor(slot) || slot < 0 || slot > 15) continue;
      var t = turrets[slot];
      if (a.op === "build") {
        if (t || typeof a.type !== "string" || !Object.prototype.hasOwnProperty.call(TDEF, a.type)) continue;
        var c = TDEF[a.type].cost;
        if (gold < c) continue;
        gold -= c;
        var sx = SLOTS[slot][0] * 100 + 50, sy = SLOTS[slot][1] * 100 + 50;
        turrets[slot] = { slot: slot, type: a.type, tier: 1, spent: c, cd: 0, x: sx, y: sy, def: TDEF[a.type],
          dmg: tierDmg(a.type, 1), range: tierRange(a.type, 1) };
        log.push([tick, "B", slot, TTYPES.indexOf(a.type)]);
        if (rec && rec.onAction) rec.onAction(tick, "B", slot, a.type, 1);
      } else if (a.op === "upgrade") {
        if (!t || t.tier >= 3) continue;
        var uc = t.def.cost * (t.tier === 1 ? 1 : 2);
        if (gold < uc) continue;
        gold -= uc; t.spent += uc; t.tier++;
        t.dmg = tierDmg(t.type, t.tier); t.range = tierRange(t.type, t.tier);
        log.push([tick, "U", slot, t.tier]);
        if (rec && rec.onAction) rec.onAction(tick, "U", slot, t.type, t.tier);
      } else if (a.op === "sell") {
        if (!t) continue;
        gold += Math.floor(t.spent * 70 / 100);
        turrets[slot] = null;
        log.push([tick, "S", slot, 0]);
        if (rec && rec.onAction) rec.onAction(tick, "S", slot, t.type, t.tier);
      }
    }
  }
  function killDead(tick, slot) {
    var any = false, i;
    for (i = 0; i < enemies.length; i++) if (enemies[i].hp <= 0) { any = true; break; }
    if (!any) return;
    var dead = [], keep = [];
    for (i = 0; i < enemies.length; i++) (enemies[i].hp <= 0 ? dead : keep).push(enemies[i]);
    enemies = keep;
    for (i = 0; i < dead.length; i++) {
      var e = dead[i];
      e.alive = false;
      gold += EDEF[e.type].bounty;
      log.push([tick, "K", e.id, slot]);
      if (rec && rec.onKill) rec.onKill(tick, e, slot);
      if (e.type === "splitter") {
        var mh = Math.max(1, Math.floor(e.maxHp / 4));
        for (var k = 0; k < 3; k++) {
          var sp = makeEnemy("splitling", e.wave, mh, e.progress);
          enemies.push(sp);
          if (rec && rec.onSpawn) rec.onSpawn(tick, sp, e.id);
        }
      }
    }
  }

  var tick;
  for (tick = 0; tick < maxTicks; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1;
      curWave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      waves.push(genWave(w + 1));
      var acts = strat.plan(buildState(tick));
      applyActions(acts, tick);
      var comp = waves[w];
      for (var qi = 0; qi < comp.length; qi++) queue.push({ tick: tick + 4 * qi, wave: w, idx: qi, type: comp[qi] });
      if (rec && rec.onWave) rec.onWave(tick, w, comp, waves[w + 1]);
    }
    // 2. spawn
    while (queue.length && queue[0].tick === tick) {
      var q = queue.shift();
      var mh0 = Math.floor(EDEF[q.type].hp * mult(q.wave) / 1000);
      var ne = makeEnemy(q.type, q.wave, mh0, 0);
      enemies.push(ne);
      if (rec && rec.onSpawn) rec.onSpawn(tick, ne, 0);
    }
    // 3. move
    var i, e;
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      var sp2 = e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      e.progress += sp2;
      if (e.progress >= e.route.len) {
        baseHp -= EDEF[e.type].leak;
        e.alive = false;
        enemies.splice(i, 1); i--;
        log.push([tick, "L", e.id, baseHp]);
        if (rec && rec.onLeak) rec.onLeak(tick, e, baseHp);
        if (baseHp <= 0) { fell = true; break; }
      } else {
        posAt(e.route, e.progress, tmp); e.x = tmp[0]; e.y = tmp[1];
      }
    }
    if (fell) {
      fallTick = tick;
      log.push([tick, "F", curWave, 0]);
      if (rec && rec.onTick) rec.onTick(tick, enemies, turrets, gold, baseHp, curWave, true);
      break;
    }
    // 4. age & heal
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.age++;
      if (e.type === "mender" && e.age % 20 === 0) {
        for (var j = 0; j < enemies.length; j++) {
          var o = enemies[j];
          if (OPT.healGroundOnly && o.air) continue;
          var dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= 150 * 150) {
            var amt = Math.floor((OPT.healByMender ? e.maxHp : o.maxHp) * 8 / 100);
            o.hp = Math.min(o.maxHp, o.hp + amt);
          }
        }
        if (rec && rec.onHeal) rec.onHeal(tick, e);
      }
    }
    // 5. turrets fire
    for (var s = 0; s < 16; s++) {
      var t = turrets[s];
      if (!t) continue;
      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      var def = t.def, r2 = t.range * t.range, cands = [];
      for (i = 0; i < enemies.length; i++) {
        e = enemies[i];
        if (e.hp <= 0) continue;
        if (e.air ? !def.air : !def.ground) continue;
        var ddx = e.x - t.x, ddy = e.y - t.y;
        if (ddx * ddx + ddy * ddy <= r2) cands.push(e);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (hasTarget) {
        var cv = [];
        for (i = 0; i < cands.length; i++) cv.push(view(cands[i]));
        var tid = strat.target({ slot: s, type: t.type, tier: t.tier, x: t.x, y: t.y, range: t.range }, cv);
        for (i = 0; i < cands.length; i++) if (cands[i].id === tid) { tgt = cands[i]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (i = 1; i < cands.length; i++) {
          var rr = cands[i].route.len - cands[i].progress, rb = tgt.route.len - tgt.progress;
          if (rr < rb) tgt = cands[i];
        }
      }
      var hits = [];
      if (def.splash > 0) {
        var sr2 = def.splash * def.splash, tx = tgt.x, ty = tgt.y;
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.hp <= 0) continue;
          if (e.air ? !def.air : !def.ground) continue;
          var sdx = e.x - tx, sdy = e.y - ty;
          if (sdx * sdx + sdy * sdy <= sr2) hits.push(e);
        }
      } else hits.push(tgt);
      for (i = 0; i < hits.length; i++) {
        e = hits[i];
        var dmg = def.pierce ? t.dmg : Math.max(1, t.dmg - e.armor);
        e.hp -= dmg;
        if (def.slow > 0) e.slow = def.slow;
      }
      t.cd = def.period;
      if (rec && rec.onShot) rec.onShot(tick, t, tgt, hits);
      killDead(tick, s);
    }
    // 6. slow timers
    for (i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (rec && rec.onTick) rec.onTick(tick, enemies, turrets, gold, baseHp, curWave, false);
  }
  var endTick = fell ? fallTick : maxTicks;
  var score = Math.round((endTick - 20) / 40 * 100) / 100;
  var str = JSON.stringify(log), h = 0x811c9dc5;
  for (var ci = 0; ci < str.length; ci++) { h ^= str.charCodeAt(ci); h = Math.imul(h, 0x01000193); }
  var hash = ("0000000" + (h >>> 0).toString(16)).slice(-8);
  return { score: score, fallTick: fallTick, log: log, hash: hash };
}

