// Parameterized strategy v1 (for tuning). P is a global param object.
var P = typeof P !== "undefined" ? P : {};
function createStrategy() {
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
  var layout = P.layout || ["cannon","flak","cannon","cannon","cannon","flak","cannon","lance","lance","cannon","flak","cannon","flak","cannon","flak","flak"];
  var order = P.order || [3,6,12,4,13,11,8,3,6,7,2,0,9,14,5,10,1,15];
  var reserveK = P.reserve || 0;
  function stepCost(sl, type) {
    if (!sl.turret) return COST[type];
    if (sl.turret.tier >= 3) return -1;
    return COST[sl.turret.type] * (sl.turret.tier === 1 ? 1 : 2);
  }
  return {
    plan: function (s) {
      var acts = [], gold = s.gold, i;
      var tier = [];
      for (i = 0; i < 16; i++) tier.push(s.slots[i].turret ? s.slots[i].turret.tier : 0);
      // Expand order: repeat order list for tiers 1..3
      var seq = [];
      for (var pass = 0; pass < 3; pass++) for (i = 0; i < order.length; i++) seq.push(order[i]);
      var want = new Array(16); for (i = 0; i < 16; i++) want[i] = 0;
      for (i = 0; i < seq.length && acts.length < 30; i++) {
        var sl = seq[i];
        want[sl]++;
        if (want[sl] > 3) continue;
        if (tier[sl] >= want[sl]) continue;
        var t = layout[sl];
        var c = tier[sl] === 0 ? COST[t] : COST[t] * (tier[sl] === 1 ? 1 : 2);
        if (gold - c < reserveK * 0) break;
        if (gold < c) break;
        gold -= c;
        if (tier[sl] === 0) acts.push({ op: "build", slot: sl, type: t }); else acts.push({ op: "upgrade", slot: sl });
        tier[sl]++;
      }
      return acts;
    },
    target: function (tu, cands) {
      var n = cands.length, i, best = cands[0], bs = -1e18;
      var ty = tu.type, dmg = DMG[ty][tu.tier - 1];
      if (ty === "cannon" || ty === "flak") {
        var rad = ty === "cannon" ? 8100 : 4900;
        for (i = 0; i < n; i++) {
          var c = cands[i], sc = 0;
          for (var j = 0; j < n; j++) {
            var o = cands[j], dx = o.x - c.x, dy = o.y - c.y;
            if (dx * dx + dy * dy <= rad) sc += Math.min(o.hp, Math.max(1, dmg - o.armor));
          }
          sc = sc * 10000 - c.remaining;
          if (sc > bs) { bs = sc; best = c; }
        }
        return best.id;
      }
      if (ty === "lance") {
        for (i = 0; i < n; i++) {
          var c2 = cands[i];
          var sc2 = Math.min(c2.hp, dmg) * 10000 - c2.remaining;
          if (sc2 > bs) { bs = sc2; best = c2; }
        }
        return best.id;
      }
      if (ty === "frost") {
        for (i = 0; i < n; i++) {
          var c3 = cands[i];
          var sc3 = (c3.slowed ? 0 : 1e9) - c3.remaining;
          if (sc3 > bs) { bs = sc3; best = c3; }
        }
        return best.id;
      }
      // bolt: menders first, then first
      for (i = 0; i < n; i++) {
        var c4 = cands[i];
        var sc4 = (c4.type === "mender" ? 1e9 : 0) - c4.remaining;
        if (sc4 > bs) { bs = sc4; best = c4; }
      }
      return best.id;
    }
  };
}

