// usage: jsc run.js -- stratfile nseeds [startSeed]
var args = typeof scriptArgs !== "undefined" ? scriptArgs : arguments;
load("sim.js");
load(args[0]);
var N = parseInt(args[1] || "30"), S0 = parseInt(args[2] || "1000");
var t0 = Date.now(), sum = 0, scores = [], minS = 1e9, maxS = 0;
for (var k = 0; k < N; k++) {
  var seed = S0 + k * 7919;
  var r = rampartSimulate(createStrategy, seed, 12020);
  scores.push(r.score); sum += r.score; minS = Math.min(minS, r.score); maxS = Math.max(maxS, r.score);
}
var r42 = rampartSimulate(createStrategy, 42, 12020);
print("mean " + (sum / N).toFixed(3) + " min " + minS + " max " + maxS + " seed42 " + r42.score + "  time " + (Date.now() - t0) + "ms");
if (args[3] === "v") print(scores.join(" "));

