// usage: jsc tune.js -- stratfile iters nTrain rngSeed [paramsFile]
var args = typeof scriptArgs !== "undefined" ? scriptArgs : arguments;
load("sim.js");
load(args[0]);
var ITER = parseInt(args[1] || "200"), NT = parseInt(args[2] || "40"), RS = parseInt(args[3] || "1");
if (args[4]) { P = JSON.parse(readFile(args[4])); }
function mul(a) { return function () { a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
var rnd = mul(RS);
var train = []; for (var i = 0; i < NT; i++) train.push(100003 + i * 104729);
function evalP(Q, seeds) {
  var save = P; P = Q; var s = 0;
  for (var i = 0; i < seeds.length; i++) s += rampartSimulate(createStrategy, seeds[i], 12020).score;
  P = save; return s / seeds.length;
}
var cur = P, curS = evalP(cur, train);
print("start " + curS.toFixed(3));
var t0 = Date.now();
for (var it = 0; it < ITER; it++) {
  var cand = mutate(cur, rnd);
  if (rnd() % 3 === 0) cand = mutate(cand, rnd);
  var cs = evalP(cand, train);
  if (cs >= curS) {
    if (cs > curS + 1e-9) print("it " + it + " " + cs.toFixed(3) + "  (" + ((Date.now() - t0) / 1000).toFixed(0) + "s)");
    cur = cand; curS = cs;
  }
}
var val = []; for (var j = 0; j < 100; j++) val.push(7000001 + j * 15485863);
print("final train " + curS.toFixed(3) + " val " + evalP(cur, val).toFixed(3));
print("PARAMS " + JSON.stringify(cur));

