  var LEAK_DMG = [1, 1, 2, 3, 2, 2, 1];
  var KEEP_X = 23.5, KEEP_Z = 11.5, WISP_H = 0.8;
  var E_HEIGHT = [0.62, 0.5, 1.12, 0.92, 0.62, 0.68, 0.36];
  var E_BAR_W = [0.46, 0.4, 0.42, 0.66, 0.5, 0.46, 0.3];
  var E_COLOR = [0x7f9468, 0xf2cf2e, 0x46e8ff, 0xe8772a, 0x9a4fe0, 0xf2f4ee, 0xb57cf0];
  var T_COLOR = [0x4a7dc4, 0xb8762e, 0xdff1ff, 0xc0182c, 0x1fa894];
  var T_MUZZLE = [0.62, 0.5, 0.78, 1.18, 0.58];
  var SHOT_PRIO = [2, 5, 1, 4, 3];

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
