function createStrategy() {
  "use strict";
  // Tuned offline by hill-climbing over hundreds of seeds (never seed 42): a fixed final layout,
  // a purchase order, splash-aware targeting, and an adaptive air-defence rule.
  var P = /*PARAMS*/;
  var TYPES = ["bolt", "cannon", "frost", "lance", "flak"];
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
  var RANGE = { bolt: 300, cannon: 260, frost: 240, lance: 360, flak: 320 };
  var PERIOD = { bolt: 8, cannon: 24, frost: 12, lance: 36, flak: 10 };
  var SPD = { grunt: 10, runner: 20, wisp: 12, brute: 6, splitter: 8, mender: 8, splitling: 12 };
  var ENAMES = ["grunt", "runner", "wisp", "brute", "splitter", "mender", "splitling"];
  var SLOTXY = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function route(pts) {
    var p = [], cum = [0], i;
    for (i = 0; i < pts.length; i++) p.push([pts[i][0] * 100 + 50, pts[i][1] * 100 + 50]);
    for (i = 1; i < p.length; i++) cum.push(cum[i - 1] + Math.abs(p[i][0] - p[i - 1][0]) + Math.abs(p[i][1] - p[i - 1][1]));
    return { p: p, cum: cum, len: cum[cum.length - 1] };
  }
  var GROUND = route([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  var AIR = route([[0,6],[21,6],[21,11],[23,11]]);
  // position from `remaining` (independent of how a host reports x/y)
  function posInto(rt, d, out, k) {
    var p = rt.p, cum = rt.cum, n = p.length, i = 1;
    if (d < 0) d = 0;
    while (i < n - 1 && cum[i] < d) i++;
    var a = p[i - 1], b = p[i], t = d - cum[i - 1];
    out[k] = a[0] + (b[0] > a[0] ? t : (b[0] < a[0] ? -t : 0));
    out[k + 1] = a[1] + (b[1] > a[1] ? t : (b[1] < a[1] ? -t : 0));
