      for (i = 0; i < n; i++) { c = cands[i]; posInto(c.type === "wisp" ? AIR : GROUND, (c.type === "wisp" ? AIR.len : GROUND.len) - c.remaining, XY, 2 * i); }
      for (i = 0; i < n; i++) {
        c = cands[i]; sc = 0;
        var cx = XY[2 * i], cy = XY[2 * i + 1];
        for (var j = 0; j < n; j++) {
          var o = cands[j], dx = XY[2 * j] - cx, dy = XY[2 * j + 1] - cy;
          if (dx * dx + dy * dy <= rad) {
            var ed = Math.min(o.hp, Math.max(1, dmg - o.armor));
            if (o.type === "mender") ed *= 1 + mb;
            if (ty === "cannon" && TW) ed *= TW[o.type];
            var rem = o.remaining;
