          }
        }
        sc = sc * 10000 - c.remaining;
        if (sc > bs) { bs = sc; best = c; }
      }
      return best.id;
    }
    if (ty === "lance") {
      for (i = 0; i < n; i++) {
        c = cands[i];
        sc = Math.min(c.hp, dmg) * (1 + tg.lb / (c.remaining + tg.uc)) * 10000 - c.remaining;
        if (c.type === "mender") sc += 1e12;
        if (sc > bs) { bs = sc; best = c; }
      }
      return best.id;
    }
    if (ty === "frost") {
      for (i = 0; i < n; i++) {
        c = cands[i];
        sc = (c.slowed ? 0 : 1e9) - c.remaining;
        if (sc > bs) { bs = sc; best = c; }
      }
      return best.id;
    }
    for (i = 0; i < n; i++) {
      c = cands[i];
      sc = (c.type === "mender" ? 1e9 : 0) - c.remaining;
      if (sc > bs) { bs = sc; best = c; }
    }
    return best.id;
  }
  return {
    plan: function (s) { try { return plan(s); } catch (e) { return []; } },
    target: function (tu, cands) { try { return target(tu, cands); } catch (e) { return undefined; } }
  };
