  var SLOTXY = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function route(pts) {
    var p = [], cum = [0], i;
    for (i = 0; i < pts.length; i++) p.push([pts[i][0] * 100 + 50, pts[i][1] * 100 + 50]);
    for (i = 1; i < p.length; i++) cum.push(cum[i - 1] + Math.abs(p[i][0] - p[i - 1][0]) + Math.abs(p[i][1] - p[i - 1][1]));
    return { p: p, cum: cum, len: cum[cum.length - 1] };
  }
  var GROUND = route([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  var AIR = route([[0,6],[21,6],[21,11],[23,11]]);
  // position from `remaining` (independent of how a host reports x/y)
  function posInto(rt, d, out, k) {
    var p = rt.p, cum = rt.cum, n = p.length, i = 1;
    if (d < 0) d = 0;
    while (i < n - 1 && cum[i] < d) i++;
    var a = p[i - 1], b = p[i], t = d - cum[i - 1];
    out[k] = a[0] + (b[0] > a[0] ? t : (b[0] < a[0] ? -t : 0));
    out[k + 1] = a[1] + (b[1] > a[1] ? t : (b[1] < a[1] ? -t : 0));
  }
  function coverage(rt, cx, cy, r) {
    var tot = 0;
    for (var i = 1; i < rt.p.length; i++) {
      var a = rt.p[i - 1], b = rt.p[i], h, lo, hi, c;
      if (a[1] === b[1]) { h = Math.abs(a[1] - cy); lo = Math.min(a[0], b[0]); hi = Math.max(a[0], b[0]); c = cx; }
      else { h = Math.abs(a[0] - cx); lo = Math.min(a[1], b[1]); hi = Math.max(a[1], b[1]); c = cy; }
      if (h > r) continue;
      var hc = Math.sqrt(r * r - h * h), l = Math.max(lo, c - hc), u = Math.min(hi, c + hc);
      if (u > l) tot += u - l;
    }
    return tot;
  }
  var AIRCOV = [];
  for (var s0 = 0; s0 < 16; s0++) {
    var row = {};
    for (var ti = 0; ti < TYPES.length; ti++) {
      var tn = TYPES[ti], arr = [];
      for (var tr = 1; tr <= 3; tr++) arr.push(coverage(AIR, SLOTXY[s0][0] * 100 + 50, SLOTXY[s0][1] * 100 + 50, RANGE[tn] + 30 * (tr - 1)));
      row[tn] = arr;
    }
    AIRCOV.push(row);
  }
  var layout = P.layout, order = P.order, tg = P.tg;
  var airK = P.airK || 0, airC = P.airC || 0;
  var TW = null;
  if (P.tw) { TW = {}; for (var twi = 0; twi < 7; twi++) TW[ENAMES[twi]] = P.tw[twi]; }
  var leaked = false;
  var XY = [];
  function hpMul(w) { var m = 1000; for (var i = 1; i < w; i++) m = Math.floor(m * 108 / 100); return m / 1000; }
  function airCap(tier) {
    var cap = 0;
    for (var s = 0; s < 16; s++) {
      if (!tier[s]) continue;
      var t = TYPES[layout[s]];
      if (t === "cannon" || t === "lance") continue;
      cap += DMG[t][tier[s] - 1] * AIRCOV[s][t][tier[s] - 1] / 12 / PERIOD[t];
    }
    return cap;
  }
  function plan(s) {
    var acts = [], gold = s.gold, i;
    if (s.baseHp < 10) leaked = true;
    var reserve = 0;
