      var sl2 = steps[i], t = TYPES[layout[sl2]];
      var c = tier[sl2] === 0 ? COST[t] : COST[t] * (tier[sl2] === 1 ? 1 : 2);
      if (gold - c < reserve) break;
      gold -= c;
      if (tier[sl2] === 0) acts.push({ op: "build", slot: sl2, type: t }); else acts.push({ op: "upgrade", slot: sl2 });
      tier[sl2]++;
    }
    return acts;
  }
  function target(tu, cands) {
    var n = cands.length, i, best = cands[0], bs = -1e18, c, sc;
    var ty = tu.type, dmg = DMG[ty][tu.tier - 1];
    if (ty === "cannon" || ty === "flak") {
      var rad = ty === "cannon" ? 8100 : 4900;
      var mb = ty === "cannon" ? tg.mb : tg.fmb, ub = ty === "cannon" ? tg.ub : tg.fub, uc = tg.uc;
      for (i = 0; i < n; i++) { c = cands[i]; posInto(c.type === "wisp" ? AIR : GROUND, (c.type === "wisp" ? AIR.len : GROUND.len) - c.remaining, XY, 2 * i); }
      for (i = 0; i < n; i++) {
