var devCS = createStrategy;
var N = parseInt(args[1] || "50"), bad = 0, sum = 0;
var t0 = Date.now();
for (var j = 0; j < N; j++) {
  var seed = 31337 + j * 999331;
  var a = rampartSimulate(finalCS, seed, 12020), b = rampartSimulate(devCS, seed, 12020);
