function buildHud(t, k) {
  nHud = 0;
  var W = window.innerWidth, H = window.innerHeight;
  var m = Math.max(14, 0.026 * H);
  // wave number + crossed blades
  var wv = R.wave[k], wtk = 0;
  for (var i = 0; i < R.waves.length; i++) if (R.waves[i].tick <= k) wtk = R.waves[i].tick;
  var pop = wv > 0 ? 1 + 0.22 * Math.max(0, 1 - (t - wtk / TPS) / 0.35) : 1;
  var dh = 0.088 * H, ic = 0.08 * H;
  hq("panel", m * 0.45, m * 0.45, ic + dh * 0.56 * Math.max(2, String(wv).length) + m * 1.6, dh + m * 0.9, 0.03, 0.04, 0.06, 0.42);
  hq("blades", m, m + (dh - ic) / 2, ic, ic, 1, 1, 1, 1);
  var dhp = dh * pop;
  hudNumber(wv, m + ic + m * 0.35, m - (dhp - dh) / 2, dhp, 1, 0.97, 0.9, 1);
  // gold
  var gy = m + dh + 0.022 * H, gh = 0.05 * H;
  hq("panel", m * 0.45, gy - m * 0.3, gh + gh * 0.56 * Math.max(3, String(R.gold[k]).length) + m * 1.5, gh + m * 0.6, 0.03, 0.04, 0.06, 0.38);
  hq("coin", m, gy, gh, gh, 1, 1, 1, 1);
  hudNumber(R.gold[k], m + gh + m * 0.3, gy, gh, 1, 0.9, 0.55, 1);
  // next-wave preview: icon + count per type
  var py = gy + gh + 0.024 * H, ph = 0.038 * H, nx = m, comp = nextComp(k), cnt = [0, 0, 0, 0, 0, 0];
  comp.forEach(function (tp) { if (EIDX[tp] < 6) cnt[EIDX[tp]]++; });
  var tot = 0; for (var c = 0; c < 6; c++) if (cnt[c]) tot++;
  hq("panel", m * 0.45, py - m * 0.3, Math.max(ph * 2, tot * (ph * 1.1 + ph * 0.5 * 2 + ph * 0.35)) + m * 0.6, ph + m * 0.6, 0.03, 0.04, 0.06, 0.34);
  for (var e = 0; e < 6; e++) {
    if (!cnt[e]) continue;
    hq("e" + e, nx, py, ph * 1.1, ph * 1.1, 1, 1, 1, 1);
    nx += ph * 1.1 + ph * 0.05;
    nx += hudNumber(cnt[e], nx, py + ph * 0.1, ph * 0.9, 0.92, 0.94, 1, 0.95) + ph * 0.45;
  }
  // base HP: 10 pips top-right, flashing as they go out
  var pd = 0.036 * H, sp = 0.046 * H, hp = R.hp[k], x0 = W - m - sp * 9 - pd, py2 = m + 0.01 * H;
  hq("panel", x0 - pd * 1.9, py2 - pd * 0.5, sp * 9 + pd * 3.1, pd * 2, 0.03, 0.04, 0.06, 0.42);
  hq("tower", x0 - pd * 1.6, py2 - pd * 0.2, pd * 1.4, pd * 1.4, 1, 1, 1, 1);
  for (var p = 0; p < 10; p++) {
    var px = x0 + p * sp, lost = p >= hp, fl = 0;
    if (lost) {
      for (var li = 0; li < R.leaks.length; li++) {
        var L = R.leaks[li];
        if (L.tick > k) break;
        if (p >= L.hp && p < L.before) { fl = Math.max(0, 1 - (t - L.tick / TPS) / 0.5); }
      }
    }
    if (!lost) hq("pip", px - pd * 0.15, py2 - pd * 0.15, pd * 1.3, pd * 1.3, 1.0, 0.36, 0.28, 1);
    else {
      hq("pipEmpty", px, py2, pd, pd, 0.5, 0.5, 0.55, 0.8);
      if (fl > 0) { var fs = pd * (1.3 + 1.2 * (1 - fl)); hq("pip", px + pd / 2 - fs / 2, py2 + pd / 2 - fs / 2, fs, fs, 1, 0.75 + 0.25 * fl, 0.6 * fl, fl); }
    }
  }
  for (var z = nHud; z < HUD_CAP; z++) { var pz = z * 12; for (var q = 0; q < 12; q++) hudPos[pz + q] = 0; }
  hudGeo.attributes.position.needsUpdate = true; hudGeo.attributes.uv.needsUpdate = true; hudGeo.attributes.aCol.needsUpdate = true;

