#!/usr/bin/env python3
import asyncio, os, base64
from playwright.async_api import async_playwright
D = os.path.dirname(os.path.abspath(__file__))
URL = "file://" + os.path.join(os.path.dirname(D), "work", "index.html")
SCRUB = "(t) => { const s = document.getElementById('scrubber'); s.value = String(t); s.dispatchEvent(new Event('input', { bubbles: true })); }"
DIFF = """async ([a, b]) => {
  const load = (u) => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = u; });
  const A = await load(a), B = await load(b), w = A.width, h = A.height;
  const c = document.createElement('canvas'); c.width = w; c.height = h; const g = c.getContext('2d');
  g.drawImage(A, 0, 0); const da = g.getImageData(0, 0, w, h).data; g.drawImage(B, 0, 0); const db = g.getImageData(0, 0, w, h).data;
  let n = 0, x0 = 1e9, y0 = 1e9, x1 = -1, y1 = -1, mx = 0;
  for (let i = 0; i < da.length; i += 4) { const d = Math.abs(da[i] - db[i]) + Math.abs(da[i+1] - db[i+1]) + Math.abs(da[i+2] - db[i+2]);
    if (d > 0) { n++; const p = i / 4, x = p % w, y = (p / w) | 0; x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); mx = Math.max(mx, d); } }
  return { n, bbox: [x0, y0, x1, y1], maxDiff: mx };
}"""
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(args=["--use-gl=angle", "--ignore-gpu-blocklist"])
        page = await b.new_page(viewport={"width": 1280, "height": 650})
        await page.goto(URL)
        await page.wait_for_timeout(4200)
        shots = []
        for path in ([50.0], [10.0, 50.0], [50.0], [80.0, 50.0]):
            for t in path:
                await page.evaluate(SCRUB, t); await page.wait_for_timeout(150)
            await page.wait_for_timeout(200)
            shots.append("data:image/png;base64," + base64.b64encode(await page.screenshot()).decode())
        for i in range(1, len(shots)):
            print("diff 0 vs", i, await page.evaluate(DIFF, [shots[0], shots[i]]))
        await b.close()
asyncio.run(main())

