#!/usr/bin/env python3
import re, os, subprocess
D = os.path.dirname(os.path.abspath(__file__))
html = open(os.path.join(os.path.dirname(D), "work", "index.html")).read()
def script(id_):
    m = re.search(r'<script id="%s">\n(.*?)</script>' % id_, html, re.S)
    return m.group(1)
strat, sim = script("rampart-strategy"), script("rampart-sim")
for name, src in (("strategy", strat), ("sim", sim)):
    bad = [w for w in ("window", "document", "THREE", "Math.random", "Date", "performance", "fetch", "XMLHttpRequest") if re.search(r"\b" + re.escape(w) + r"\b", src)]
    print(name, "forbidden identifiers:", bad or "none", "| bytes", len(src))
open(os.path.join(D, "x_strategy.js"), "w").write(strat)
open(os.path.join(D, "x_sim.js"), "w").write(sim)
test = r'''
var before = Object.getOwnPropertyNames(this).slice();
load("x_strategy.js");
var g1 = Object.getOwnPropertyNames(this).filter(function (k) { return before.indexOf(k) < 0; });
var b2 = Object.getOwnPropertyNames(this).slice();
load("x_sim.js");
var g2 = Object.getOwnPropertyNames(this).filter(function (k) { return b2.indexOf(k) < 0; });
print("globals from strategy script: " + JSON.stringify(g1) + "  from sim script: " + JSON.stringify(g2));
var A = function () { return { plan: function (s) { var a = [], g = s.gold; for (var k = 0; k < s.slots.length; k++) { var sl = s.slots[k]; if (!sl.turret && g >= 50) { a.push({ op: "build", slot: sl.slot, type: "bolt" }); g -= 50; } } return a; } }; };
var B = function () { return { plan: function (s) {
  if (s.wave === 1) return [{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}];
  if (s.wave === 3) return [{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}];
  if (s.wave === 6) return [{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}]; return []; } }; };
var ra = rampartSimulate(A, 42, 12020), rb = rampartSimulate(B, 7, 12020);
print("vector A: " + [ra.score, ra.fallTick, ra.log.length, ra.hash].join(" ") + (ra.hash === "82a5353d" && ra.score === 25.38 && ra.fallTick === 1035 && ra.log.length === 166 ? "  OK" : "  MISMATCH"));
print("vector B: " + [rb.score, rb.fallTick, rb.log.length, rb.hash].join(" ") + (rb.hash === "2e8858d7" && rb.score === 10.93 && rb.fallTick === 457 && rb.log.length === 48 ? "  OK" : "  MISMATCH"));
var a1 = createStrategy(), a2 = createStrategy();
print("fresh objects distinct: " + (a1 !== a2 && a1.plan !== a2.plan));
var r1 = rampartSimulate(createStrategy, 42, 2020), r2 = rampartSimulate(createStrategy, 42, 2020);
print("seed42@2020 repeatable: " + (r1.hash === r2.hash) + " score " + r1.score + " fallTick " + r1.fallTick);
var t0 = Date.now(), s = 0; for (var i = 0; i < 5; i++) s += rampartSimulate(createStrategy, 123457 + i * 86243, 12020).score;
print("5 full games (to the fall, max 300 waves): mean " + (s / 5).toFixed(2) + " in " + (Date.now() - t0) + " ms");
'''
open(os.path.join(D, "x_test.js"), "w").write(test)
print(subprocess.run(["/System/Library/Frameworks/JavaScriptCore.framework/Versions/A/Helpers/jsc", "x_test.js"], cwd=D, capture_output=True, text=True).stdout + subprocess.run(["/System/Library/Frameworks/JavaScriptCore.framework/Versions/A/Helpers/jsc", "x_test.js"], cwd=D, capture_output=True, text=True).stderr)

